sp_SalvarEmpresa	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_SalvarEmpresa`(\n\n    IN p_idEmpresa INT, IN p_Nome VARCHAR(200), IN p_CNPJ VARCHAR(20),\n\n    IN p_Telefone VARCHAR(20), IN p_Email VARCHAR(100), IN p_codigoMunicipio VARCHAR(7)\n\n)\nBEGIN\n\n    UPDATE Empresa SET Nome=p_Nome, CNPJ=p_CNPJ, Telefone=p_Telefone,\n\n        Email=p_Email, codigoMunicipio=p_codigoMunicipio\n\n    WHERE idEmpresa=p_idEmpresa;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
